mapper.select:
select 
from user_collect
where user_id = #{userId}
and sku_id = #{skuId}
and is_deleted = 0
limit 1

mapper.update:
update user_collect set
                        is_deleted = 1,
                        update_time = now()
where user_id = #{userId}
  and sku_id = #{skuId}
  and is_deleted = 0
